{ inputs, pkgs, ... }:

{
  imports = [
    ./hardware-configuration.nix
    ../../modules/system/nvidia.nix
    ../../modules/system/audio.nix
    ../../modules/system/gaming.nix
    ../../modules/system/locale.nix
  ];

  # --- Boot ---
  boot = {
    loader = {
      systemd-boot.enable = true;
      efi.canTouchEfiVariables = true;
    };
    kernelParams = [
      "quiet"
      "splash"
      "nvidia_drm.modeset=1"
      "nvidia_drm.fbdev=1"
    ];
    # Latest kernel for best NVMe + hardware support
    kernelPackages = pkgs.linuxPackages_latest;
  };

  # --- Networking ---
  networking = {
    hostName = "BEBRA-PC";
    networkmanager.enable = true;
  };

  # --- Hardware ---
  hardware = {
    bluetooth = {
      enable = true;
      powerOnBoot = true;
    };
    graphics = {
      enable = true;
      enable32Bit = true;
    };
  };

  # --- Services ---
  services = {
    upower.enable = true;
    power-profiles-daemon.enable = true;

    # X server for XWayland
    xserver.enable = true;

    # Hyprland via display manager
    displayManager.sddm = {
      enable = true;
      wayland.enable = true;
    };
  };

  # --- Hyprland ---
  programs.hyprland = {
    enable = true;
    package = inputs.hyprland.packages.${pkgs.stdenv.hostPlatform.system}.hyprland;
    portalPackage = inputs.hyprland.packages.${pkgs.stdenv.hostPlatform.system}.xdg-desktop-portal-hyprland;
    withUWSM = true;
  };

  # --- Users ---
  users.users.bebra = {
    isNormalUser = true;
    shell = pkgs.zsh;
    extraGroups = [ "wheel" "networkmanager" "audio" "video" "input" ];
  };

  # --- Programs ---
  programs = {
    zsh.enable = true;
    dconf.enable = true;
    # Clash Verge Rev — tun mode requires setcap on the binary
    clash-verge = {
      enable       = true;
      tunMode      = true;   # setcap NET_ADMIN for TUN
      autoStart    = true;   # XDG autostart entry
      serviceMode  = true;   # system service for clash core
    };
    # Thunar
    thunar = {
      enable = true;
      plugins = with pkgs.xfce; [
        thunar-archive-plugin
        thunar-volman
        thunar-media-tags-plugin
      ];
    };
  };

  # --- Flatpak ---
  services.flatpak.enable = true;
  # XDG portals already configured above

  # Install Flathub + Nvidia runtimes declaratively
  systemd.services.flatpak-setup = {
    description = "Setup Flatpak remotes and Nvidia runtimes";
    wantedBy = [ "multi-user.target" ];
    after = [ "network-online.target" ];
    wants = [ "network-online.target" ];
    serviceConfig.Type = "oneshot";
    serviceConfig.RemainAfterExit = true;
    path = [ pkgs.flatpak ];
    script = ''
      flatpak remote-add --if-not-exists flathub https://dl.flathub.org/repo/flathub.flatpakrepo
      # Freedesktop runtimes (base for everything)
      flatpak install -y flathub org.freedesktop.Platform//24.08 org.freedesktop.Sdk//24.08 || true
      # GNOME runtime
      flatpak install -y flathub org.gnome.Platform//47 org.gnome.Sdk//47 || true
      # KDE runtime
      flatpak install -y flathub org.kde.Platform//6.8 org.kde.Sdk//6.8 || true
      # Nvidia GL extension (matches host driver automatically)
      flatpak install -y flathub org.freedesktop.Platform.GL.nvidia-open || true
      flatpak install -y flathub org.freedesktop.Platform.VAAPI.nvidia || true
  # --- Portals ---
  xdg.portal = {
    enable = true;
    extraPortals = [ pkgs.xdg-desktop-portal-gtk ];
  };

  # --- System packages ---
  environment.systemPackages = with pkgs; [
    git
    wget
    curl
    vim
    file
    gvfs
    tumbler          # Thunar thumbnail generator
    ffmpegthumbnailer
    poppler          # PDF thumbnails
    libgsf           # ODF thumbnails
    inputs.noctalia.packages.${pkgs.stdenv.hostPlatform.system}.default
  ];

  # --- Nix settings ---
  nix = {
    settings = {
      experimental-features = [ "nix-command" "flakes" ];
      auto-optimise-store = true;
      trusted-users = [ "root" "bebra" ];
      extra-substituters = [
        "https://hyprland.cachix.org"
        "https://noctalia.cachix.org"
      ];
      extra-trusted-public-keys = [
        "hyprland.cachix.org-1:a7pgxzMz7+chwVL3/pzj6jIBMioiJM7ypFP8PwtkuGc="
        "noctalia.cachix.org-1:pCOR47nnMEo5thcxNDtzWpOxNFQsBRglJzxWPp3dkU4="
      ];
    };
    gc = {
      automatic = true;
      dates = "weekly";
      options = "--delete-older-than 14d";
    };
  };

  system.stateVersion = "25.05";
}

