    wget
    curl
    vim
    file
    gvfs
    tumbler
    ffmpegthumbnailer
    poppler
    libgsf
    inputs.noctalia.packages.${pkgs.stdenv.hostPlatform.system}.default
  ];

  # --- Nix settings ---
