let
  # HyDE fonts not in nixpkgs — fetched as tarballs
  hydeFonts = pkgs.stdenvNoCC.mkDerivation {
    name = "hyde-fonts";
    srcs = [
      (pkgs.fetchurl {
        url  = "https://raw.githubusercontent.com/HyDE-Project/HyDE/master/Source/arcs/Font_CascadiaCove.tar.gz";
        hash = "sha256-DP8z2RhA7gMKp4VZD/sLlq3gHVqXJnnpBN1e3cLFxkY=";
      })
      (pkgs.fetchurl {
        url  = "https://raw.githubusercontent.com/HyDE-Project/HyDE/master/Source/arcs/Font_MapleNerd.tar.gz";
        hash = "sha256-FzPRZVPe3UtP3V35OQID6nKJkxMLNnGH3zcBVJ01Gkc=";
      })
      (pkgs.fetchurl {
        url  = "https://raw.githubusercontent.com/HyDE-Project/HyDE/master/Source/arcs/Font_MaterialDesign.tar.gz";
        hash = "sha256-iu6W/YGQBlCJTHjUCDf1sKCXOB58tEbilEoRn4mNUSg=";
      })
      (pkgs.fetchurl {
        url  = "https://raw.githubusercontent.com/HyDE-Project/HyDE/master/Source/arcs/Font_MononokiNerd.tar.gz";
        hash = "sha256-zNF4YIu9GPVJKlblgUCwk9vdIYFpP2lFi22f0HW6A6M=";
      })
    ];
    sourceRoot = ".";
    unpackPhase = ''
      for src in $srcs; do
        tar -xzf "$src" || true
      done
    '';
    installPhase = ''
      find . -name "*.ttf" -o -name "*.otf" -o -name "*.woff2" | while read f; do
        install -Dm644 "$f" "$out/share/fonts/hyde/$(basename "$f")"
      done
    '';
  };
in
{
  home.packages = with pkgs; [
    # Launchers / UI
    rofi-wayland
    libnotify  # notify-send CLI

