    slurp
    grim

    # Wallpaper
    hyprpwcenter

    # Idle / lock
    hypridle
    hyprlock

    # Screen color temperature
    hyprsunset

    # Wayland tools
    wlr-randr
    wl-mirror
    xorg.xev

    # Fonts — nixpkgs
    nerd-fonts.jetbrains-mono
    nerd-fonts.fira-code
    font-awesome
    noto-fonts
    noto-fonts-cjk-sans
    noto-fonts-emoji

    # Fonts — HyDE
